function weatherLocationDict(region=getPath(`${WEATHER}/Region/@code`)){
  const list=WEATHER_LOCATIONS[region];
  if(!list) return null;
  return Object.fromEntries(list.map(([id,name])=>[id,[name,name]]));
}
function weatherLocationRecord(code=getPath(`${WEATHER}/Location/@code`), region=getPath(`${WEATHER}/Region/@code`)){
  return WEATHER_LOCATIONS[region]?.find(([id])=>String(id)===String(code))||null;
}
function applyWeatherClimate(){
  const rec=weatherLocationRecord();
  if(!rec||rec[2]==null) return;
  setPath(`${WEATHER}/@heatingDegreeDay`, rec[2]);
}
function clientRegionName(){
  return String(getPath(`${CLIENT_STREET}/Province`)||"").trim().toUpperCase();
}
function weatherCodeForRegion(name=clientRegionName()){
  return Object.entries(WEATHER_REGIONS).find(([,labels])=>String(labels[0]).toUpperCase()===String(name||"").toUpperCase())?.[0]||"";
}
function syncWeatherRegionToClient(){
  const code=weatherCodeForRegion();
  if(!code) return false;
  if(String(getPath(`${WEATHER}/Region/@code`))!==String(code)){
    setCoded(`${WEATHER}/Region`, code, WEATHER_REGIONS);
  }
  ensureWeatherLocationForRegion();
  return true;
}
function onClientRegionChange(){
  if(!syncWeatherRegionToClient()) return;
  renderWeatherTab();
  saveSession();
}
