function codedOptions(dict, order=null, showCode=false){
  const keys=order||Object.keys(dict);
  return keys.filter(k=>dict[k]).map(id=>({
    id,
    label:showCode?`${dict[id][0]} (${id})`:dict[id][0]
  }));
}
/** True when text looks like an auto-built 10-digit HOT2000 ceiling code. */
function isCeilingNumericCode(s){
  return /^\d{10}$/.test(String(s||"").trim());
}
/** Match a Layers child element to a catalog code (by English label or code attr). */
function matchCeilingLayerEl(el, dict, fallback="0"){
  if(!el) return fallback;
  const code=String(av(el,"code")||"");
  const en=(el.querySelector(":scope > English")?.textContent||"").replace(/\s+/g," ").trim();
  if(en){
    const exact=Object.entries(dict).find(([,v])=>v[0].replace(/\s+/g," ")===en);
    if(exact) return exact[0];
    const soft=Object.entries(dict).find(([,v])=>{
      const label=v[0].replace(/\s+/g," ");
      return en.includes(label.slice(0,22)) || label.includes(en.slice(0,22));
    });
    if(soft) return soft[0];
  }
  if(dict[code]) return code;
  return code||fallback;
}
function ceilingCodeNode(id){
  if(!id || id===CEILING_TYPE_MODE_USER || id===CEILING_TYPE_MODE_NEW) return null;
  const key=String(id).trim();
  let node=xp(`/HouseFile/Codes/Ceiling//Code[@id='${key}']`);
  if(node) return node;
  if(isCeilingNumericCode(key)) node=xp(`/HouseFile/Codes/Ceiling//Code[@value='${key}']`);
  return node||null;
}
function resolveCeilingAssemblyId(idOrValue){
  const key=String(idOrValue||"").trim();
  if(!key || key===CEILING_TYPE_MODE_USER || key===CEILING_TYPE_MODE_NEW) return key;
  const node=ceilingCodeNode(key);
  if(node) return node.getAttribute("id")||key;
  return key;
}
/** Prefer a human-readable label over a 10-digit numeric code when both exist. */
function ceilingPickDisplayLabel({storedLabel="", favLabel="", storedValue="", computedLabel=""}={}){
  const numeric=storedValue && isCeilingNumericCode(storedValue)
    ? storedValue
    : (isCeilingNumericCode(storedLabel)?storedLabel:computedLabel);
  const candidates=[storedLabel, favLabel, storedValue, computedLabel]
    .map(s=>String(s||"").trim())
    .filter(Boolean);
  const custom=candidates.find(s=>!isCeilingNumericCode(s));
  if(custom) return custom;
  return candidates[0]||numeric||DEFAULT_CEILING_CODE_LABEL;
}
function setCeilingCodeDisplayLabel(codeId, displayLabel){
  const node=ceilingCodeNode(resolveCeilingAssemblyId(codeId));
  if(!node) return null;
  const label=String(displayLabel||"").trim();
  if(!label) return node;
  childText(node,"Label",label);
  childText(node,"Description",label);
  return node;
}
function migrateCeilingFavouriteId(oldId, newId, label){
  const from=String(oldId||"").trim();
  const to=String(newId||"").trim();
  if(!from || !to || from===to) return;
  const favs=ceilingFavourites();
  const hit=favs.find(f=>f.id===from);
  if(!hit) return;
  const next=favs.filter(f=>f.id!==from && f.id!==to);
  next.unshift({id:to, label:String(label||hit.label||to).trim()||to});
  localStorage.setItem("h2kCeilingFavourites", JSON.stringify(next));
}
/** Keep favourite entries aligned when a code id/value/label changes. */
function syncFavouritesForCeilingCode(codeNode, displayLabel){
  if(!codeNode) return;
  const id=String(codeNode.getAttribute("id")||"").trim();
  const value=String(codeNode.getAttribute("value")||"").trim();
  const label=String(displayLabel||"").trim();
  if(!id || !label) return;
  const favs=ceilingFavourites();
  let changed=false;
  const next=favs.map(f=>{
    const node=ceilingCodeNode(f.id);
    if(f.id===id || f.id===value || node===codeNode){
      changed=true;
      return {id, label};
    }
    return f;
  });
  if(changed) localStorage.setItem("h2kCeilingFavourites", JSON.stringify(next));
}
function ceilingDisplayLabelFromForm(formEl){
  const codeLabelEl=formEl?.querySelector("[data-ceiling-code-label]")
    ||formEl?.querySelector('[name="codeLabel"]');
  const codeValueEl=formEl?.querySelector("[data-ceiling-code-value]")
    ||formEl?.querySelector('[name="codeValue"]');
  const raw=String(codeLabelEl?.value||"").trim();
  const numeric=String(codeValueEl?.value||"").trim();
  if(raw && !isCeilingNumericCode(raw)) return raw;
  if(raw) return raw;
  return numeric||DEFAULT_CEILING_CODE_LABEL;
}
function ceilingLabelIsCustomized(formEl, displayLabel=null){
  const label=String(displayLabel||"").trim();
  if(label && !isCeilingNumericCode(label)) return true;
  const codeLabelEl=formEl?.querySelector("[data-ceiling-code-label]")
    ||formEl?.querySelector('[name="codeLabel"]');
  const codeValueEl=formEl?.querySelector("[data-ceiling-code-value]")
    ||formEl?.querySelector('[name="codeValue"]');
  const raw=String(codeLabelEl?.value||"").trim();
  const numeric=String(codeValueEl?.value||"").trim();
  if(codeLabelEl?.dataset?.customized==="true") return true;
  return !!raw && raw!==numeric && !isCeilingNumericCode(raw);
}
function captureCeilingSaveSnapshot(formEl){
  if(!formEl?.querySelector("[data-ceiling-editor]")) return null;
  const displayLabel=ceilingDisplayLabelFromForm(formEl);
  return {
    displayLabel,
    customized:ceilingLabelIsCustomized(formEl, displayLabel)
  };
}
/** Read Code Selector field values from a ceiling Code node (or favourite override). */
function readCeilingCodeState(codeNode, assemblyId=null){
  if(!codeNode) return null;
  const id=assemblyId||codeNode.getAttribute("id")||"";
  const layers=codeNode.querySelector(":scope > Layers");
  const structure=matchCeilingLayerEl(layers?.querySelector("StructureType"), CEILING_STRUCTURE_TYPES, "2");
  const sizeDict=ceilingComponentSizes(structure);
  const framingDict=ceilingFramingOptions(structure);
  const locksFraming=ceilingStructureLocksFraming(structure);
  const isPanel=ceilingStructureIsPanel(structure);
  const componentSize=matchCeilingLayerEl(layers?.querySelector("ComponentTypeSize"), sizeDict, firstDictCode(sizeDict)||"0");
  const spacing=matchCeilingLayerEl(layers?.querySelector("Spacing"), framingDict,
    locksFraming?"0":(firstDictCode(framingDict)||"0"));
  const insulation1=matchCeilingLayerEl(layers?.querySelector("InsulationLayer1"), CEILING_INSULATION_1, "0");
  const insulation2=matchCeilingLayerEl(layers?.querySelector("InsulationLayer2"), CEILING_INSULATION_2, "0");
  const interior=matchCeilingLayerEl(layers?.querySelector("Interior"), CEILING_INTERIOR, "0");
  const computedLabel=buildCeilingCodeLabel({
    structureType:structure,
    componentSize,
    spacing:locksFraming?"0":spacing,
    insulation1:isPanel?"0":insulation1,
    insulation2:isPanel?"0":insulation2,
    interior
  });
  const storedLabel=codeNode.querySelector("Label")?.textContent?.trim()||"";
  const storedValue=codeNode.getAttribute("value")?.trim()||"";
  const fav=ceilingFavourites().find(f=>f.id===id || f.id===storedValue);
  const numericCode=storedValue && isCeilingNumericCode(storedValue)
    ? storedValue
    : (isCeilingNumericCode(storedLabel)?storedLabel:computedLabel);
  const displayLabel=ceilingPickDisplayLabel({
    storedLabel,
    favLabel:fav?.label,
    storedValue,
    computedLabel
  });
  const labelCustomized=displayLabel!==computedLabel && displayLabel!==numericCode;
  return {
    structureType:structure,
    componentSize,
    spacing:locksFraming?"0":spacing,
    insulation1:isPanel?"0":insulation1,
    insulation2:isPanel?"0":insulation2,
    interior,
    displayLabel,
    numericCode,
    labelCustomized,
    computedLabel
  };
}
function ceilingAssemblyShowsSelector(mode){
  if(!mode || mode===CEILING_TYPE_MODE_USER) return false;
  if(mode===CEILING_TYPE_MODE_NEW) return true;
  if(ceilingFavouriteIds().has(String(mode))) return true;
  // Show selector for any ceiling code so custom labels can be edited/saved.
  return !!ceilingCodeNode(mode);
}
function ceilingFormHasCodeSelector(formEl){
  return !!formEl?.querySelector("[data-ceiling-code-selector]");
}
function ceilingSelectorIsOpen(formEl){
  const section=formEl?.querySelector("[data-ceiling-code-selector]");
  return !!section && !section.hidden;
}
function shouldPersistCeilingCode(assembly, formEl, displayLabel){
  if(!assembly || assembly===CEILING_TYPE_MODE_USER) return false;
  if(assembly===CEILING_TYPE_MODE_NEW) return true;
  if(displayLabel && !isCeilingNumericCode(displayLabel)) return true;
  if(ceilingFormHasCodeSelector(formEl)) return true;
  return ceilingAssemblyIsEditable(assembly);
}
function ceilingAssemblyIsEditable(mode){
  return ceilingAssemblyShowsSelector(mode);
}
/** HOT2000-style 10-digit ceiling code: 2 + Structure + Size + Spacing + Ins1 + Ins2 + Interior, padded. */
function buildCeilingCodeLabel({structureType="2", componentSize="0", spacing="0", insulation1="0", insulation2="0", interior="0"}={}){
  const part=v=>{
    const d=String(v??"0").replace(/\D/g,"");
    return d===""?"0":d;
  };
  const raw="2"+[structureType,componentSize,spacing,insulation1,insulation2,interior].map(part).join("");
  return (raw+"0000000000").slice(0,10);
}
function ceilingTypeOptions(){
  const order=["2","1","3","4","5"];
  const items=order.filter(id=>CEILING_TYPES[id]).map(id=>({id,label:CEILING_TYPES[id][0]}));
  if(xmlDoc){
    xpa("/HouseFile/House/Components/Ceiling/Construction/Type").forEach(t=>{
      const code=String(av(t,"code")||"");
      if(!code || items.some(i=>i.id===code)) return;
      items.push({id:code,label:t.querySelector(":scope > English")?.textContent?.trim()||`Ceiling type ${code}`});
    });
  }
  return items;
}
function ceilingFavourites(){
  try{
    const raw=JSON.parse(localStorage.getItem("h2kCeilingFavourites")||"[]");
    if(!Array.isArray(raw)) return [];
    return raw.map(x=>{
      if(typeof x==="string") return {id:x,label:x};
      const id=String(x?.id||"");
      if(!id) return null;
      return {id,label:String(x.label||id)};
    }).filter(Boolean);
  }catch(_){ return []; }
}
function ceilingFavouriteIds(){
  const ids=new Set();
  ceilingFavourites().forEach(f=>{
    ids.add(String(f.id));
    const node=ceilingCodeNode(f.id);
    if(node){
      const cid=node.getAttribute("id");
      const val=node.getAttribute("value");
      if(cid) ids.add(String(cid));
      if(val) ids.add(String(val));
    }
  });
  return ids;
}
function saveCeilingFavourite(id, label){
  if(!id || id===CEILING_TYPE_MODE_USER || id===CEILING_TYPE_MODE_NEW) return;
  const codeLabel=String(label||id).trim()||String(id);
  const next=ceilingFavourites().filter(f=>f.id!==String(id));
  next.unshift({id:String(id), label:codeLabel});
  localStorage.setItem("h2kCeilingFavourites", JSON.stringify(next));
}
function ceilingAssemblyOptions(preferredOnly=true){
  const favs=ceilingFavourites();
  const favIds=new Set(favs.map(f=>f.id));
  const items=[];
  // Favourites first — Ceiling Type shows the saved Code Label in red.
  favs.forEach(f=>{
    const node=ceilingCodeNode(f.id);
    const xmlLabel=node?.querySelector("Label")?.textContent?.trim();
    const storedValue=node?.getAttribute("value")?.trim()||"";
    const label=ceilingPickDisplayLabel({
      storedLabel:xmlLabel,
      favLabel:f.label,
      storedValue,
      computedLabel:f.id
    });
    const id=node?.getAttribute("id")||f.id;
    items.push({id, label, fav:true, user:true});
  });
  xpa("/HouseFile/Codes/Ceiling//Code").forEach(c=>{
    const id=c.getAttribute("id");
    if(!id || favIds.has(id)) return;
    const isUser=!!c.closest("UserDefined");
    if(preferredOnly && isUser) return;
    const label=c.querySelector("Label")?.textContent||c.getAttribute("value")||id;
    items.push({id,label,user:isUser,fav:false});
  });
  items.push({id:CEILING_TYPE_MODE_USER,label:"User specified"});
  items.push({id:CEILING_TYPE_MODE_NEW,label:"Create New Codes"});
  return items;
}
function fromRValueDisplay(rsi){
  if(rsi===""||rsi==null) return "";
  const n=Number(rsi);
  if(!Number.isFinite(n)) return rsi;
  return unitMode==="imperial"?num(n*RSI_TO_R,2):num(n,2);
}
function toRsiValue(display){
  const n=Number(display);
  if(!Number.isFinite(n)) return display;
  return unitMode==="imperial"?num(n/RSI_TO_R,4):num(n,4);
}
function rValueFieldLabel(){
  return unitMode==="imperial"?"R-Value (R)":"R-Value (RSI)";
}
function fromRValueDisplayDoor(rsi){
  if(rsi===""||rsi==null) return "";
  const n=Number(rsi);
  if(!Number.isFinite(n)) return rsi;
  return unitMode==="imperial"?num(n*RSI_TO_R,3):num(n,3);
}
function numInputField(key,label,value,measure="",decimals=2,extra=""){
  let disp=measure?fromSI(value,measure):value;
  if(disp!==""&&disp!=null&&Number.isFinite(Number(disp))) disp=Number(disp).toFixed(decimals);
  const u=measure?unitLabel(measure):"";
  const step=(10**-decimals).toFixed(decimals);
  return `<label class="field"><span>${esc(label)}${u?` (${u})`:""}</span><input name="${key}" type="number" inputmode="decimal" step="${step}" value="${esc(disp)}" ${extra}></label>`;
}
function doorTypeDict(){return Object.fromEntries(Object.entries(DOOR_TYPES).map(([k,[en,fr]])=>[k,[en,fr]]));}
function doorTypeOptions(){
  const items=Object.entries(DOOR_TYPES).map(([id,v])=>({id,label:v[0]}));
  if(xmlDoc){
    xpa("/HouseFile/House/Components//Door/Construction/Type").forEach(t=>{
      const code=String(av(t,"code")||"");
      if(!code || items.some(i=>i.id===code)) return;
      items.push({id:code,label:t.querySelector(":scope > English")?.textContent?.trim()||`Door type ${code}`});
    });
  }
  return items;
}
