function programModeFromClass(className){
  const cls=String(className||"");
  if(cls.includes("ONrh.OnProgram")) return "ontarioRef";
  if(cls.includes("ERS2020NBC")) return "ers2020nbc";
  if(cls.includes("ERS.ErsProgram")) return "ers";
  return "";
}
function captureProgramErsValues(){
  const values={};
  xpa("/HouseFile/Program/Results/Ers/*").forEach(el=>{
    values[el.tagName]=el.getAttribute("value")??"";
  });
  return values;
}
function setProgramMetaAttrs(el){
  el.setAttribute("xmlns:xsi", PROGRAM_XMLNS.xsi);
  el.setAttribute("xmlns:xsd", PROGRAM_XMLNS.xsd);
}
function appendProgramLabels(parent, en, fr){
  const labels=xmlDoc.createElement("Labels");
  setProgramMetaAttrs(labels);
  const enEl=xmlDoc.createElement("English");
  enEl.textContent=en;
  const frEl=xmlDoc.createElement("French");
  frEl.textContent=fr;
  labels.append(enEl, frEl);
  parent.appendChild(labels);
}
function copyProgramVersionBlock(tag, source){
  const defaults=PROGRAM_VERSION_DEFAULTS[tag]||PROGRAM_VERSION_DEFAULTS.Version;
  const block=xmlDoc.createElement(tag);
  setProgramMetaAttrs(block);
  const src=source?.querySelector(`:scope > ${tag}`);
  block.setAttribute("major", src?.getAttribute("major")||defaults.major);
  block.setAttribute("minor", src?.getAttribute("minor")||defaults.minor);
  block.setAttribute("build", src?.getAttribute("build")||defaults.build);
  const labels=xmlDoc.createElement("Labels");
  const enText=src?.querySelector(":scope > Labels > English")?.textContent||defaults.en;
  const frText=src?.querySelector(":scope > Labels > French")?.textContent||defaults.fr;
  const enEl=xmlDoc.createElement("English");
  enEl.textContent=enText;
  const frEl=xmlDoc.createElement("French");
  frEl.textContent=frText;
  labels.append(enEl, frEl);
  block.appendChild(labels);
  return block;
}
function appendProgramMainVermiculite(main){
  const verm=xmlDoc.createElement("Vermiculite");
  verm.setAttribute("code","3");
  const en=xmlDoc.createElement("English");
  en.textContent="No Vermiculite";
  const fr=xmlDoc.createElement("French");
  fr.textContent="Pas de Vermiculite";
  verm.append(en, fr);
  main.appendChild(verm);
}
function buildProgramOptions(){
  const options=xmlDoc.createElement("Options");
  setProgramMetaAttrs(options);
  const main=xmlDoc.createElement("Main");
  Object.entries(PROGRAM_MAIN_ATTRS).forEach(([k,v])=>main.setAttribute(k,v));
  appendProgramMainVermiculite(main);
  options.appendChild(main);
  const comments=xmlDoc.createElement("RURComments");
  comments.setAttribute("xml:space","preserve");
  options.appendChild(comments);
  const measures=xmlDoc.createElement("ResiliencyMeasures");
  measures.setAttribute("basementSlabInsulated","false");
  measures.setAttribute("moistureProofCrawlSpace","false");
  measures.setAttribute("waterproofing","false");
  measures.setAttribute("roofingMembrane","false");
  measures.setAttribute("minR10ContinuousExposedFloors","false");
  measures.setAttribute("backwaterValve","false");
  measures.setAttribute("sumpPump","false");
  measures.setAttribute("smartThermostats","false");
  measures.setAttribute("evCharger","");
  measures.setAttribute("elecPanelUpgraded","false");
  options.appendChild(measures);
  return options;
}
function buildProgramResults(ersValues){
  const results=xmlDoc.createElement("Results");
  setProgramMetaAttrs(results);
  const ers=xmlDoc.createElement("Ers");
  PROGRAM_ERS_FIELDS.forEach(name=>{
    const el=xmlDoc.createElement(name);
    const value=ersValues[name]??PROGRAM_ERS_DEFAULTS[name]??"";
    el.setAttribute("value", value);
    ers.appendChild(el);
  });
  results.appendChild(ers);
  return results;
}
function buildProgramElement(modeId, preservedErs={}){
  const mode=PROGRAM_MODES[modeId]||PROGRAM_MODES.ers;
  const existing=xp("/HouseFile/Program");
  const prog=xmlDoc.createElement("Program");
  prog.setAttribute("class", mode.className);
  appendProgramLabels(prog, mode.en, mode.fr);
  prog.appendChild(copyProgramVersionBlock("Version", existing));
  prog.appendChild(copyProgramVersionBlock("SdkVersion", existing));
  prog.appendChild(buildProgramOptions());
  prog.appendChild(buildProgramResults(preservedErs));
  return prog;
}
function placeProgramNode(prog){
  const houseFile=xmlDoc.documentElement;
  xp("/HouseFile/Program")?.remove();
  const allResults=xp("/HouseFile/AllResults");
  if(allResults) houseFile.insertBefore(prog, allResults.nextSibling);
  else houseFile.appendChild(prog);
}
function removeProgramNode(){
  xp("/HouseFile/Program")?.remove();
}
function getProgramModeId(){
  const prog=xp("/HouseFile/Program");
  if(!prog) return "general";
  const fromClass=programModeFromClass(prog.getAttribute("class"));
  if(fromClass) return fromClass;
  const en=String(getPath("/HouseFile/Program/Labels/English")||"").trim().toLowerCase();
  if(!en) return "ers";
  const match=Object.values(PROGRAM_MODES).find(p=>p.en.toLowerCase()===en);
  if(match) return match.id;
  if(/ontario\s+ref/.test(en)) return "ontarioRef";
  if(/2020\s+nbc|nbc\s+2020/.test(en)) return "ers2020nbc";
  if(/energuide/.test(en)) return "ers";
  return "ers";
}
function programStructureMatches(id){
  const mode=PROGRAM_MODES[id]||PROGRAM_MODES.ers;
  const prog=xp("/HouseFile/Program");
  if(id==="general") return !prog;
  if(!prog) return false;
  if(prog.getAttribute("class")!==mode.className) return false;
  if(String(getPath("/HouseFile/Program/Labels/English")||"").trim()!==mode.en) return false;
  if(!xp("/HouseFile/Program/Results/Ers")) return false;
  if(xp("/HouseFile/Program/Results/Tsv")) return false;
  if(!xp("/HouseFile/Program/Options/Main/Vermiculite")) return false;
  return true;
}
function setProgramMode(id){
  const mode=PROGRAM_MODES[id]||PROGRAM_MODES.ers;
  if(id==="general"){
    removeProgramNode();
    return;
  }
  const preserved=captureProgramErsValues();
  placeProgramNode(buildProgramElement(id, preserved));
}
function syncProgramModeUI(){
  const el=$("#programMode");
  if(!el||!xmlDoc) return;
  const id=getProgramModeId();
  if(el.value!==id) el.value=id;
}
/** Write the toolbar Program dropdown into /HouseFile/Program before validate, save, or export. */
function syncProgramModeFromUI(){
  const el=$("#programMode");
  if(!el||!xmlDoc) return;
  const id=el.value;
  if(!PROGRAM_MODES[id]) return;
  if(programStructureMatches(id)) return;
  setProgramMode(id);
}
function ensureProgramModeDefault(){
  const id=getProgramModeId();
  if(id==="general"){
    removeProgramNode();
    return;
  }
  if(!xp("/HouseFile/Program")){
    setProgramMode("ers");
    return;
  }
  if(!String(getPath("/HouseFile/Program/Labels/English")||"").trim()){
    setProgramMode("ers");
    return;
  }
  if(!programStructureMatches(id)) setProgramMode(id);
}
function applyProgramModeFromUI(value){
  if(!xmlDoc) return;
  setProgramMode(value);
  syncProgramModeUI();
  invalidateReviewUnlock("Program changed — click top-bar <strong>Validate</strong> again before Export or Generate Net (GJ/a).");
  saveSession();
  toast(`Program set to ${PROGRAM_MODES[value]?.en||value}`);
  const {view, screen}=parseHash();
  if(view==="systems" && screen==="program" && value==="general"){
    routeTo("systems","temperatures");
  }else{
    applyRoute();
  }
}

function decodeTemplate(){
  const raw=atob(TEMPLATE_B64), bytes=new Uint8Array(raw.length);
  for(let i=0;i<raw.length;i++) bytes[i]=raw.charCodeAt(i);
  return new TextDecoder("utf-8").decode(bytes);
}
function parseXML(text){
  const doc=new DOMParser().parseFromString(text,"application/xml");
  const err=doc.querySelector("parsererror");
  if(err) throw new Error("Invalid XML: "+err.textContent.slice(0,180));
  return doc;
}
function xp(path,ctx=xmlDoc){
  return xmlDoc.evaluate(path,ctx,null,XPathResult.FIRST_ORDERED_NODE_TYPE,null).singleNodeValue;
}
function xpa(path,ctx=xmlDoc){
  const r=xmlDoc.evaluate(path,ctx,null,XPathResult.ORDERED_NODE_SNAPSHOT_TYPE,null), a=[];
  for(let i=0;i<r.snapshotLength;i++) a.push(r.snapshotItem(i)); return a;
}
function ensureEl(path){
  const existing=xp(path); if(existing) return existing;
  if(!xmlDoc || !path.startsWith("/HouseFile")) return null;
  const parts=path.split("/").filter(Boolean).slice(1);
  let cur=xmlDoc.documentElement;
  for(const part of parts){
    const m=part.match(/^([A-Za-z0-9]+)(?:\[(\d+)\])?$/);
    if(!m) return null;
    const tag=m[1], idx=m[2]?Number(m[2]):1;
    let matches=[...cur.children].filter(x=>x.tagName===tag);
    while(matches.length<idx){
      cur.appendChild(xmlDoc.createElement(tag));
      matches=[...cur.children].filter(x=>x.tagName===tag);
    }
    cur=matches[idx-1];
  }
  return cur;
}
function getPath(path){
  if(path.includes("/@")){const [p,a]=path.split("/@"); const n=xp(p); return n?n.getAttribute(a)??"":"";}
  const n=xp(path); return n?n.textContent:"";
}
function setPath(path,value){
  if(path.includes("/@")){const i=path.lastIndexOf("/@"), p=path.slice(0,i), a=path.slice(i+2), n=ensureEl(p); if(n)n.setAttribute(a,String(value));}
  else {const n=ensureEl(path); if(n)n.textContent=String(value);}
}
function setCoded(path, code, dict){
  const n=ensureEl(path); if(!n) return;
  n.setAttribute("code", code);
  const labels=dict[code];
  let en=n.querySelector(":scope > English"), fr=n.querySelector(":scope > French");
  if(labels && labels[0]){
    if(!en){en=xmlDoc.createElement("English"); n.appendChild(en);}
    if(!fr){fr=xmlDoc.createElement("French"); n.appendChild(fr);}
    en.textContent=labels[0]; fr.textContent=labels[1];
  } else {
    if(en) en.textContent="";
    if(fr) fr.textContent="";
  }
}
function applyCodedDefault(path, code, dict, attrs={}){
  setCoded(path, code, dict);
  const n=ensureEl(path);
  if(n) Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,String(v)));
}
function childText(n, tag, value){
  if(!n) return;
  let c=[...n.children].find(x=>x.tagName===tag);
  if(!c){c=xmlDoc.createElement(tag); n.appendChild(c);}
  if(value!==undefined) c.textContent=String(value);
  return c;
}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function num(v,d=4){const n=Number(v); return Number.isFinite(n)?Number(n.toFixed(d)):0;}
function unitLabel(measure){if(!measure)return ""; if(measure==="area")return unitMode==="imperial"?"ft²":"m²"; if(measure==="volume")return unitMode==="imperial"?"ft³":"m³"; if(measure==="length")return unitMode==="imperial"?"ft":"m"; if(measure==="anemometer-height-ft")return "ft"; if(measure==="mm")return unitMode==="imperial"?"in":"mm"; if(measure==="door")return unitMode==="imperial"?"in":"m"; if(measure==="ela-imperial")return unitMode==="imperial"?"in²":"cm²"; if(measure==="ela")return "cm²"; if(measure==="celsius")return "°C"; if(measure==="fahrenheit")return "°F"; if(measure==="pv-temp-coeff")return unitMode==="imperial"?"%/°F":"%/°C"; if(measure==="imp-gal-day")return "Imp."; if(measure==="imp-gal")return "Imp gal"; if(measure==="kwh-day")return "kWh/day"; if(measure==="kwh-year")return "kWh/year"; if(measure==="kW")return "kW"; if(measure==="min-occ-day")return "min/occ/day"; if(measure==="minutes")return "minutes"; if(measure==="min-day")return "Min/Day"; if(measure==="shower-occ-week")return "shower/occ/week"; if(measure==="loads-occ-week")return "loads/occ/week"; if(measure==="cycle-occ-week")return "cycle/occ/week"; if(measure==="imp-gal-occ-day")return "Imp gal"; if(measure==="percent")return "%"; if(measure==="hours")return "hours"; if(measure==="ach")return "ACH"; if(measure==="pa")return "Pa"; if(measure==="watts")return "W"; if(measure==="vent-min-display")return unitMode==="imperial"?"cfm":"L/s"; if(measure==="vent-flow-ls")return "L/s"; if(measure==="vent-flow-cfm")return "cfm"; if(measure==="duct-length-ft")return "ft"; if(measure==="duct-diameter-in")return "in"; if(measure==="duct-insulation-r")return "R"; return "";}
function fromSI(v,m){if(v===""||v==null)return ""; let n=Number(v); if(!Number.isFinite(n))return v; if(m==="fahrenheit")return n*9/5+32; if(m==="anemometer-height-ft")return n*3.280839895; if(m==="ela-imperial")return num(unitMode==="imperial"?n/6.4516:n,1); if(m==="ela")return num(n,1); if(m==="vent-flow-rate"&&unitMode==="imperial")return num(n*LS_TO_CFM,1); if(m==="vent-flow-cfm")return num(n*LS_TO_CFM,4); if(m==="duct-length-ft")return num(n*3.280839895,5); if(m==="duct-diameter-in")return Math.round(n/25.4); if(m==="duct-insulation-r")return num(n,5); if(!m||unitMode!=="imperial")return n; if(m==="area")n*=10.7639104167; else if(m==="volume")n*=35.3146667215; else if(m==="length")n*=3.280839895; else if(m==="mm")n/=25.4; else if(m==="door")n*=39.37007874; else if(m==="imp-gal-day"||m==="imp-gal"||m==="imp-gal-occ-day")n/=4.54609; return num(n,3);}
function toSI(v,m){let n=Number(v); if(!Number.isFinite(n))return v; if(m==="fahrenheit")return num((n-32)*5/9,4); if(m==="anemometer-height-ft")return num(n/3.280839895,4); if(m==="ela-imperial")return num(unitMode==="imperial"?n*6.4516:n,4); if(m==="ela")return num(n,4); if(m==="vent-flow-rate"&&unitMode==="imperial")return num(n/LS_TO_CFM,4); if(m==="vent-flow-cfm")return num(n/LS_TO_CFM,4); if(m==="duct-length-ft")return num(n/3.280839895,5); if(m==="duct-diameter-in")return num(n*25.4,4); if(m==="duct-insulation-r")return num(n,5); if(unitMode!=="imperial")return n; if(m==="area")n/=10.7639104167; else if(m==="volume")n/=35.3146667215; else if(m==="length")n/=3.280839895; else if(m==="mm")n*=25.4; else if(m==="door")n/=39.37007874; else if(m==="imp-gal-day"||m==="imp-gal"||m==="imp-gal-occ-day")n*=4.54609; return num(n,4);}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2600);}

function fieldHTML(path,label,type="text",cls="",measure="",maxLength=0,decimals=null,disabled=false){
  type=type||"text";
  let raw=getPath(path);
  if(maxLength>0 && type!=="checkbox") raw=String(raw??"").slice(0,maxLength);
  let val=type==="checkbox"?getPath(path):(measure||type==="number"?fromSI(raw,measure):raw);
  if(decimals!=null && type==="number" && val!=="" && val!=null && Number.isFinite(Number(val))){
    val=Number(val).toFixed(decimals);
  }
  const u=unitLabel(measure);
  if(type==="checkbox") return `<label class="check ${cls}"><input data-xml-path="${esc(path)}" data-xml-type="checkbox" type="checkbox" ${String(getPath(path)).toLowerCase()==="true"?"checked":""}${disabled?" disabled":""}> ${esc(label)}</label>`;
  const maxAttr=maxLength>0?` maxlength="${maxLength}"`:"";
  const stepAttr=decimals!=null?` step="${esc((10**-decimals).toFixed(decimals))}" data-decimals="${decimals}"`:` step="any"`;
  const disabledAttr=disabled?" disabled":"";
  return `<label class="field ${cls}"><span>${esc(label)}${u?` (${u})`:""}</span><input data-xml-path="${esc(path)}" data-xml-type="${type}" data-measure="${esc(measure||"")}" type="${type==="number"?"number":type}" value="${esc(val)}"${stepAttr}${maxAttr}${disabledAttr}></label>`;
}
/** Ontario FSAs start with K, L, M, N, or P. Letter positions never use D F I O Q U. */
const ON_POSTAL_FIRST="KLMNP";
const ON_POSTAL_LETTER="ABCEGHJKLMNPRSTVWXYZ";
function formatOntarioPostal(raw){
  const cleaned=String(raw??"").toUpperCase().replace(/[^A-Z0-9]/g,"");
  // Don't shift characters if the first letter is a non-Ontario FSA (e.g. pasted H/T/V codes).
  if(cleaned && /[A-Z]/.test(cleaned[0]) && !ON_POSTAL_FIRST.includes(cleaned[0])) return "";
  let out="";
  for(const ch of cleaned){
    if(out.length>=6) break;
    const pos=out.length;
    if(pos%2===0){
      if(pos===0){ if(!ON_POSTAL_FIRST.includes(ch)) continue; }
      else if(!ON_POSTAL_LETTER.includes(ch)) continue;
      out+=ch;
    }else{
      if(!/\d/.test(ch)) continue;
      out+=ch;
    }
  }
  return out.length>3?`${out.slice(0,3)} ${out.slice(3)}`:out;
}
function isOntarioPostal(value){
  return /^[KLMNP]\d[ABCEGHJKLMNPRSTVWXYZ] \d[ABCEGHJKLMNPRSTVWXYZ]\d$/.test(formatOntarioPostal(value));
}
function postalFieldHTML(path,label,cls=""){
  const raw=String(getPath(path)??"").trim();
  const val=raw?formatOntarioPostal(raw):"";
  const hintId="postalOntarioHint";
  return `<label class="field ${cls}"><span>${esc(label)}</span><input data-xml-path="${esc(path)}" data-xml-type="postal-ontario" type="text" value="${esc(val)}" maxlength="7" placeholder="A1A 1A1" inputmode="text" autocomplete="postal-code" spellcheck="false" autocapitalize="characters" aria-describedby="${hintId}" title="Ontario postal code only (starts with K, L, M, N, or P)" pattern="[KkLlMmNnPp]\\d[A-Za-z] ?\\d[A-Za-z]\\d"><small id="${hintId}" class="field-hint">Ontario only (K/L/M/N/P) · e.g. M5V 3L9</small></label>`;
}
function selectHTML(path,label,entries,cls="",coded=true,disabled=false){
  const cur=coded?getPath(path+"/@code"):getPath(path);
  let list=Array.isArray(entries)?entries.map(x=>Array.isArray(x)?x:[x.id, Array.isArray(x.label)?x.label[0]:x.label]):Object.entries(entries);
  if(coded && cur && !list.some(([id])=>String(id)===String(cur))){
    const en=getPath(path+"/English")||`Code ${cur}`;
    list=[[cur,[en,en]]].concat(list);
  }
  const opts=list.map(([id,lab])=>{
    const text=Array.isArray(lab)?lab[0]:lab;
    return `<option value="${esc(id)}" ${String(id)===String(cur)?"selected":""}>${esc(text)}</option>`;
  }).join("");
  return `<label class="field ${cls}"><span>${esc(label)}</span><select data-xml-path="${esc(path)}" data-xml-type="${coded?"coded":"text"}"${disabled?" disabled":""}>${opts}</select></label>`;
}
function regionSelect(path,label,cls="",disabled=false){
  const cur=getPath(path);
  const opts=REGIONS.map(r=>`<option value="${esc(r)}" ${r===cur?"selected":""}>${esc(r)}</option>`).join("");
  return `<label class="field ${cls}"><span>${esc(label)}</span><select data-xml-path="${esc(path)}" data-xml-type="text"${disabled?" disabled":""}>${opts}</select></label>`;
}

const CLIENT_STREET="/HouseFile/ProgramInformation/Client/StreetAddress";
const CLIENT_MAIL="/HouseFile/ProgramInformation/Client/MailingAddress";
const CLIENT_NAME="/HouseFile/ProgramInformation/Client/Name";

function syncPartsFromClientName(name){
  const trimmed=String(name??"").trim();
  const parts=trimmed.split(/\s+/);
  setPath(`${CLIENT_NAME}/First`, parts[0]||"");
  setPath(`${CLIENT_NAME}/Last`, parts.slice(1).join(" ")||"");
  setPath(`${CLIENT_MAIL}/Name`, trimmed);
}

function ensureClientNameFromParts(){
  const name=getPath(`${CLIENT_MAIL}/Name`).trim();
  if(name) return;
  const first=getPath(`${CLIENT_NAME}/First`).trim();
  const last=getPath(`${CLIENT_NAME}/Last`).trim();
  if(first||last) syncPartsFromClientName([first,last].filter(Boolean).join(" "));
}

function syncMailingFromClient(){
  ensureClientNameFromParts();
  ["Street","UnitNumber","City","Province","PostalCode"].forEach(key=>{
    setPath(`${CLIENT_MAIL}/${key}`, getPath(`${CLIENT_STREET}/${key}`));
  });
}

function bindClientAddressSync(root){
  const clientPaths=new Set([
    `${CLIENT_MAIL}/Name`,
    "/HouseFile/ProgramInformation/Client/Telephone",
    `${CLIENT_STREET}/Street`,
    `${CLIENT_STREET}/UnitNumber`,
    `${CLIENT_STREET}/City`,
    `${CLIENT_STREET}/Province`,
    `${CLIENT_STREET}/PostalCode`
  ]);
  root.querySelectorAll("[data-xml-path]").forEach(el=>{
    if(!clientPaths.has(el.dataset.xmlPath)) return;
    el.addEventListener("change",()=>{
      if(el.dataset.xmlPath===`${CLIENT_MAIL}/Name`) syncPartsFromClientName(el.value);
      syncMailingFromClient();
    });
  });
}

function bindXml(root, dictFor){
  root.querySelectorAll("[data-xml-path]").forEach(el=>{
    const apply=()=>{
      const path=el.dataset.xmlPath, type=el.dataset.xmlType||"text", measure=el.dataset.measure||"";
      if(type==="checkbox") setPath(path, el.checked?"true":"false");
      else if(type==="coded"){
        const dict=dictFor?.(el, path);
        if(dict) setCoded(path, el.value, dict);
        else setPath(path+"/@code", el.value);
      } else if(type==="postal-ontario"){
        const formatted=formatOntarioPostal(el.value);
        el.value=formatted;
        setPath(path, formatted);
        if(formatted && !isOntarioPostal(formatted)){
          el.setCustomValidity("Enter a valid Ontario postal code (starts with K, L, M, N, or P).");
        }else{
          el.setCustomValidity("");
        }
      } else if(type==="pv-cell-temp"){
        let value=el.value;
        const stored=toPvCellTemp(value);
        const decimals=el.dataset.decimals?Number(el.dataset.decimals):null;
        if(decimals!=null && value!=="" && Number.isFinite(Number(value))){
          el.value=Number(fromPvCellTemp(stored)).toFixed(decimals);
        }
        setPath(path, stored);
      } else if(type==="pv-temp-coeff"){
        let value=el.value;
        const stored=toPvTempCoeff(value);
        const decimals=el.dataset.decimals?Number(el.dataset.decimals):null;
        if(decimals!=null && value!=="" && Number.isFinite(Number(value))){
          el.value=Number(fromPvTempCoeff(stored)).toFixed(decimals);
        }
        setPath(path, stored);
      } else {
        let value=el.value;
        if(el.maxLength>0) value=value.slice(0, el.maxLength);
        const decimals=el.dataset.decimals?Number(el.dataset.decimals):null;
        if(decimals!=null && value!=="" && Number.isFinite(Number(value))){
          value=Number(value).toFixed(decimals);
          el.value=value;
        }
        setPath(path, measure?toSI(value,measure):value);
      }
      if(isEnergyModelPath(path)){
        invalidateReviewUnlock("Envelope/Systems changed — click top-bar <strong>Validate</strong> again before Export or Generate Net (GJ/a).");
      }else{
        updateReview();
      }
      saveSession();
    };
    if(el.dataset.xmlType==="postal-ontario"){
      el.addEventListener("input",()=>{
        const start=el.selectionStart;
        const before=el.value;
        const formatted=formatOntarioPostal(el.value);
        if(formatted!==before){
          el.value=formatted;
          // Keep caret near end while typing; space insert shifts by one.
          const pos=Math.min(formatted.length, (start||0)+(formatted.length>before.length?1:0));
          try{ el.setSelectionRange(pos,pos); }catch(_){}
        }
        if(formatted && !isOntarioPostal(formatted)){
          el.setCustomValidity("Enter a valid Ontario postal code (starts with K, L, M, N, or P).");
        }else{
          el.setCustomValidity("");
        }
      });
    }
    el.addEventListener("change", apply);
  });
}

