const ENERGY_STAR_JUST = {
  "0":""
};
function isoToDmy(value){
  const s=String(value??"").trim();
  const iso=s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if(iso) return `${iso[3]}/${iso[2]}/${iso[1]}`;
  return s;
}
function dmyToIso(value){
  const s=String(value??"").trim();
  const dmy=s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if(dmy) return `${dmy[3]}-${dmy[2]}-${dmy[1]}`;
  return s;
}
function justValue(el){
  if(!el) return "";
  return (el.getAttribute("value")||el.textContent||"").trim();
}
function setJustValue(el, value){
  if(!el) return;
  const text=value??"";
  if(el.hasAttribute("value")) el.setAttribute("value", text);
  el.textContent=text;
}
function insulationWrap(){
  const j=ensureEl("/HouseFile/ProgramInformation/Justifications");
  return j.querySelector(":scope > CorrectedInsulation")||j.appendChild(xmlDoc.createElement("CorrectedInsulation"));
}

function justificationState(){
  const j=ensureEl("/HouseFile/ProgramInformation/Justifications");
  const poss=j.querySelector(":scope > PossessionDate");
  const vol=j.querySelector(":scope > HeatingVolumeDecrease");
  const ins=j.querySelector(":scope > CorrectedInsulation");
  const other=j.querySelector(":scope > Other");
  const star=j.querySelector(":scope > EnergyStar");
  return {
    nameplate:j.getAttribute("nameplateEfficiency")==="true",
    combustion:j.getAttribute("combustionTestEfficiency")==="true",
    heatingCorrection:j.getAttribute("heatingCorrection")==="true",
    possession:poss?.getAttribute("selected")==="true",
    possessionDate:isoToDmy(justValue(poss)),
    heatingVolume:vol?.getAttribute("selected")==="true",
    heatingVolumeValue:justValue(vol),
    ceilings:ins?.querySelector(":scope > Ceilings")?.getAttribute("selected")==="true",
    ceilingsValue:justValue(ins?.querySelector(":scope > Ceilings")),
    walls:ins?.querySelector(":scope > Walls")?.getAttribute("selected")==="true",
    wallsValue:justValue(ins?.querySelector(":scope > Walls")),
    basement:ins?.querySelector(":scope > Basement")?.getAttribute("selected")==="true",
    basementValue:justValue(ins?.querySelector(":scope > Basement")),
    achCorrection:j.getAttribute("achCorrection")==="true",
    twoBlower:j.getAttribute("twoBlowerDoors")==="true",
    other:other?.getAttribute("selected")==="true",
    otherText:justValue(other),
    over18:j.getAttribute("over18Months")==="true",
    energyStar:star?.getAttribute("code")||"0"
  };
}
function justCheck(key,label,checked,extra=""){
  return `<label class="check"><input type="checkbox" name="${esc(key)}" ${checked?"checked":""} ${extra}> ${esc(label)}</label>`;
}
function justField(name,value,attrs=""){
  return `<div class="just-field"><input name="${esc(name)}" value="${esc(value||"")}" ${attrs}></div>`;
}
function justBlank(){return `<span class="just-empty" aria-hidden="true"></span>`;}
function openJustifications(){
  const s=justificationState();
  const starOpts=Object.assign({}, ENERGY_STAR_JUST);
  if(s.energyStar && !(s.energyStar in starOpts)) starOpts[s.energyStar]=s.energyStar;
  $("#justificationsFields").innerHTML=`
    ${justCheck("nameplate","Efficiency from nameplate",s.nameplate)}${justBlank()}
    ${justCheck("combustion","Efficiency from combustion test",s.combustion)}${justBlank()}
    ${justCheck("heatingCorrection","Heating system correction",s.heatingCorrection)}${justBlank()}
    ${justCheck("possession","Possession date",s.possession,`data-enables="possessionDate"`)}
    <div class="just-field"><span>Date:</span><input name="possessionDate" value="${esc(s.possessionDate)}" placeholder="dd/mm/yyyy" inputmode="numeric" autocomplete="off" maxlength="10"></div>
    ${justCheck("heatingVolume","Heating volume decrease",s.heatingVolume,`data-enables="heatingVolumeValue"`)}
    ${justField("heatingVolumeValue",s.heatingVolumeValue,`type="text"`)}
    ${justCheck("ceilings","Corrected insulation value in ceilings",s.ceilings,`data-enables="ceilingsValue"`)}
    ${justField("ceilingsValue",s.ceilingsValue,`type="text"`)}
    ${justCheck("walls","Corrected insulation value in walls",s.walls,`data-enables="wallsValue"`)}
    ${justField("wallsValue",s.wallsValue,`type="text"`)}
    ${justCheck("basement","Corrected insulation value in basement",s.basement,`data-enables="basementValue"`)}
    ${justField("basementValue",s.basementValue,`type="text"`)}
    ${justCheck("achCorrection","ACH correction",s.achCorrection)}${justBlank()}
    ${justCheck("twoBlower","Two blower doors used",s.twoBlower)}${justBlank()}
    <div class="just-other">
      ${justCheck("other","Other",s.other,`data-enables="otherText"`)}
      ${justField("otherText",s.otherText,`type="text"`)}
    </div>
    ${justCheck("over18","18 months+",s.over18)}${justBlank()}
    <label class="just-energystar"><span>ENERGY STAR</span>
      <select name="energyStar" disabled>${Object.entries(starOpts).map(([id,lab])=>`<option value="${esc(id)}" ${String(id)===String(s.energyStar)?"selected":""}>${esc(lab)}</option>`).join("")}</select>
    </label>`;
  const root=$("#justificationsFields");
  root.querySelectorAll("[data-enables]").forEach(cb=>{
    const field=root.querySelector(`[name="${cb.dataset.enables}"]`);
    const sync=()=>{ if(field) field.disabled=!cb.checked; };
    cb.addEventListener("change", sync);
    sync();
  });
  $("#justificationsDialog").showModal();
}
function saveJustifications(){
  const form=$("#justificationsForm");
  const checked=name=>form.querySelector(`[name="${name}"]`)?.checked?"true":"false";
  const field=(name)=>{
    const el=form.querySelector(`[name="${name}"]`);
    return el && !el.disabled ? el.value : null;
  };
  const j=ensureEl("/HouseFile/ProgramInformation/Justifications");
  j.setAttribute("nameplateEfficiency", checked("nameplate"));
  j.setAttribute("combustionTestEfficiency", checked("combustion"));
  j.setAttribute("heatingCorrection", checked("heatingCorrection"));
  j.setAttribute("achCorrection", checked("achCorrection"));
  j.setAttribute("twoBlowerDoors", checked("twoBlower"));
  j.setAttribute("over18Months", checked("over18"));
  const poss=childText(j,"PossessionDate");
  poss.setAttribute("selected", checked("possession"));
  const possVal=field("possessionDate");
  if(possVal!==null) setJustValue(poss, dmyToIso(possVal));
  const vol=childText(j,"HeatingVolumeDecrease");
  vol.setAttribute("selected", checked("heatingVolume"));
  const volVal=field("heatingVolumeValue");
  if(volVal!==null) setJustValue(vol, volVal);
  const wrap=insulationWrap();
  [["ceilings","Ceilings","ceilingsValue"],["walls","Walls","wallsValue"],["basement","Basement","basementValue"]].forEach(([key,tag,valName])=>{
    const n=childText(wrap, tag);
    n.setAttribute("selected", checked(key));
    const val=field(valName);
    if(val!==null) setJustValue(n, val);
  });
  const other=childText(j,"Other");
  other.setAttribute("selected", checked("other"));
  const otherVal=field("otherText");
  if(otherVal!==null) setJustValue(other, otherVal);
  ensureEl("/HouseFile/ProgramInformation/Justifications/EnergyStar");
  $("#justificationsDialog").close();
  saveSession();
  toast("Justifications saved");
}

function renderInfoTab(){
  const t=$("#screen-house-info"); if(!t) return;
  const info=ensureEl("/HouseFile/ProgramInformation/Information");
  const rows=[...info.children].filter(n=>n.tagName==="Info");
  t.innerHTML=`<article class="section-card"><h3>Info</h3>
    <p class="tab-help">Extensible information fields used for partner and NRCan communication (Info. 1–10 appear in the XML results).</p>
    <table class="info-table"><thead><tr><th>ID</th><th>Value</th><th></th></tr></thead>
    <tbody>${rows.map((n,i)=>`<tr>
      <td><input data-info-i="${i}" data-info-k="code" value="${esc(n.getAttribute("code")||"")}"></td>
      <td><input data-info-i="${i}" data-info-k="value" value="${esc(n.textContent||"")}"></td>
      <td><button type="button" class="mini danger" data-info-del="${i}">Delete</button></td>
    </tr>`).join("")||`<tr><td colspan="3">No info rows. Click Add to create one.</td></tr>`}</tbody></table>
    <button type="button" class="button secondary" id="addInfoBtn">Add</button>
  </article>`;
  t.querySelectorAll("[data-info-i]").forEach(el=>el.addEventListener("change",()=>{
    const n=rows[Number(el.dataset.infoI)]; if(!n) return;
    if(el.dataset.infoK==="code") n.setAttribute("code", el.value);
    else n.textContent=el.value;
  }));
  t.querySelectorAll("[data-info-del]").forEach(b=>b.addEventListener("click",()=>{
    rows[Number(b.dataset.infoDel)]?.remove(); renderInfoTab();
  }));
  $("#addInfoBtn")?.addEventListener("click",()=>{
    const used=rows.map(n=>n.getAttribute("code")||"");
    let i=1; while(used.includes(`Info. ${i}`)) i++;
    const n=xmlDoc.createElement("Info"); n.setAttribute("code",`Info. ${i}`); info.appendChild(n); renderInfoTab();
  });
}

