function bindWeatherLocationSearch(root){
  const combo=root.querySelector("[data-weather-location-combo]");
  if(!combo) return;
  const input=combo.querySelector("[data-weather-location-input]");
  const toggle=combo.querySelector("[data-weather-location-toggle]");
  const listEl=combo.querySelector("[data-weather-location-list]");
  const region=getPath(`${WEATHER}/Region/@code`);
  const locations=WEATHER_LOCATIONS[region]||[];
  const currentCode=String(getPath(`${WEATHER}/Location/@code`)||"");
  let activeIndex=-1;

  function setOpen(open){
    listEl.hidden=!open;
    input.setAttribute("aria-expanded", open?"true":"false");
    toggle?.setAttribute("aria-expanded", open?"true":"false");
  }

  function setActiveItem(index){
    const items=[...listEl.querySelectorAll("li")];
    if(!items.length){ activeIndex=-1; return; }
    activeIndex=Math.max(0, Math.min(index, items.length-1));
    items.forEach((li,i)=>li.classList.toggle("active", i===activeIndex));
    items[activeIndex]?.scrollIntoView({block:"nearest"});
  }

  function renderList(query, {preferCurrent=false}={}){
    const matches=filterWeatherLocations(locations, query);
    const preferred=preferCurrent
      ? matches.findIndex(m=>String(m.id)===currentCode)
      : -1;
    activeIndex=preferred>=0?preferred:(matches.length?0:-1);
    listEl.innerHTML=matches.length
      ? matches.map(({id,name},i)=>`
        <li role="option" data-weather-location-id="${esc(id)}"
          aria-selected="${String(id)===currentCode?"true":"false"}"
          class="${i===activeIndex?"active":""}${String(id)===currentCode?" current":""}">${esc(name)}</li>`).join("")
      : `<li class="weather-combo-empty" role="presentation">No matching locations</li>`;
    setOpen(true);
    if(activeIndex>=0){
      requestAnimationFrame(()=>listEl.querySelector("li.active")?.scrollIntoView({block:"nearest"}));
    }
  }

  function openBrowseList(){
    renderList("", {preferCurrent:true});
  }

  function selectLocation(code){
    const dict=weatherLocationDict();
    if(!dict?.[code]) return;
    setCoded(`${WEATHER}/Location`, code, dict);
    applyWeatherClimate();
    updateReview();
    saveSession();
    renderWeatherTab();
  }

  function pickHighlighted(){
    const item=listEl.querySelector("li.active[data-weather-location-id]")
      || listEl.querySelector("li[data-weather-location-id]");
    if(item) selectLocation(item.dataset.weatherLocationId);
  }

  input.addEventListener("input",()=>{
    renderList(input.value);
  });
  input.addEventListener("paste",()=>{
    setTimeout(()=>{
      const code=findWeatherLocationByName(input.value);
      if(code) selectLocation(code);
      else renderList(input.value);
    }, 0);
  });
  input.addEventListener("focus",()=>{
    input.select();
    openBrowseList();
  });
  input.addEventListener("click",()=>{
    if(listEl.hidden) openBrowseList();
  });
  toggle?.addEventListener("mousedown",e=>{
    e.preventDefault();
    if(listEl.hidden){
      input.focus();
      openBrowseList();
    } else {
      setOpen(false);
      input.value=weatherLocationName();
    }
  });
  input.addEventListener("blur",()=>setTimeout(()=>{
    if(combo.contains(document.activeElement)) return;
    setOpen(false);
    input.value=weatherLocationName();
  }, 150));
  input.addEventListener("keydown",e=>{
    const items=[...listEl.querySelectorAll("li[data-weather-location-id]")];
    if(e.key==="ArrowDown"){
      e.preventDefault();
      if(listEl.hidden) openBrowseList();
      else setActiveItem(activeIndex<0?0:activeIndex+1);
    } else if(e.key==="ArrowUp"){
      e.preventDefault();
      if(listEl.hidden) openBrowseList();
      else setActiveItem(activeIndex<=0?0:activeIndex-1);
    } else if(e.key==="Enter"){
      if(!listEl.hidden && items.length){
        e.preventDefault();
        pickHighlighted();
      }
    } else if(e.key==="Escape"){
      setOpen(false);
      input.value=weatherLocationName();
    }
  });
  listEl.addEventListener("mousedown",e=>{
    const li=e.target.closest("li[data-weather-location-id]");
    if(li){
      e.preventDefault();
      selectLocation(li.dataset.weatherLocationId);
    }
  });
}

