const FUEL_COST_DEFAULTS = {
  Electricity:"Ottawa97",
  NaturalGas:"Ottawa08",
  Oil:"Ottawa08",
  Propane:"Ottawa08",
  Wood:"Sth Ont"
};
/** Snapshot of monthly Ontario rate blocks from the template (HOT2000 fuelLib monthly rates). */
const FUEL_COST_MONTHLY_BLOCKS = {
  Electricity:{unitsCode:"1", unitsEn:"kWhr", unitsFr:"kWh", minUnits:"0", minCharge:"10",
    blocks:[["250","0.0999"],["99999","0.0702"],["0","0"],["0","0"]]},
  NaturalGas:{unitsCode:"4", unitsEn:"m³", unitsFr:"m³", minUnits:"0", minCharge:"14",
    blocks:[["30","0.5338"],["85","0.5277"],["170","0.5229"],["99999","0.5194"]]},
  Oil:{unitsCode:"2", unitsEn:"Litre", unitsFr:"Litre", minUnits:"0", minCharge:"0",
    blocks:[["99999","1.175"],["0","0"],["0","0"],["0","0"]]},
  Propane:{unitsCode:"2", unitsEn:"Litre", unitsFr:"Litre", minUnits:"0", minCharge:"0",
    blocks:[["99999","0.72"],["0","0"],["0","0"],["0","0"]]},
  Wood:{unitsCode:"4", unitsEn:"Cords", unitsFr:"Cordes", minUnits:"0", minCharge:"0",
    blocks:[["99999","210"],["0","0"],["0","0"],["0","0"]]}
};
function getFuelRatePeriod(){
  const cur=String(getPath("/HouseFile/FuelCosts/@ratePeriod")||"").trim();
  return cur==="Annual"?"Annual":"Monthly";
}
function applyFuelRateBlocks(period){
  const annual=period==="Annual";
  Object.entries(FUEL_COST_MONTHLY_BLOCKS).forEach(([tag,cfg])=>{
    const base=`/HouseFile/FuelCosts/${tag}/Fuel[1]`;
    setPath(`${base}/Label`, FUEL_COST_DEFAULTS[tag]);
    setPath(`${base}/Units/@code`, cfg.unitsCode);
    setPath(`${base}/Units/English`, cfg.unitsEn);
    setPath(`${base}/Units/French`, cfg.unitsFr);
    setPath(`${base}/Minimum/@units`, cfg.minUnits);
    setPath(`${base}/Minimum/@charge`, annual?String(Number(cfg.minCharge)*12):cfg.minCharge);
    cfg.blocks.forEach((pair,i)=>{
      const [units,cost]=pair;
      const n=Number(units);
      // Annual mode uses yearly tiers (monthly tier × 12). Leave open-ended 99999 caps alone.
      const scaled=annual && n>0 && n<90000?String(n*12):units;
      setPath(`${base}/RateBlocks/Block${i+1}/@units`, scaled);
      setPath(`${base}/RateBlocks/Block${i+1}/@costPerUnit`, cost);
    });
  });
}
function setFuelRatePeriod(period){
  const value=period==="Annual"?"Annual":"Monthly";
  // Kept on the live document for web UI round-trip only. Stripped on HOT2000 export
  // because Desktop does not recognize @ratePeriod and defaults the radio to Annual.
  setPath("/HouseFile/FuelCosts/@ratePeriod", value);
  applyFuelRateBlocks(value);
}
function ensureFuelCostDefaults(){
  setPath("/HouseFile/FuelCosts/@includeCostCalculations","true");
  if(!getPath("/HouseFile/FuelCosts/@library")) setPath("/HouseFile/FuelCosts/@library","fuelLib.flc");
  if(!getPath("/HouseFile/FuelCosts/@ratePeriod")) setPath("/HouseFile/FuelCosts/@ratePeriod", "Monthly");
  Object.entries(FUEL_COST_DEFAULTS).forEach(([tag,label])=>{
    setPath(`/HouseFile/FuelCosts/${tag}/Fuel[1]/Label`, label);
  });
  // Ensure block structure matches the selected period (Monthly by default).
  applyFuelRateBlocks(getFuelRatePeriod());
}


