function afterSystemBind(root){
  bindXml(root, (el,path)=>{
    if(path.includes("EnergySource")||path.endsWith("/EnergySource")) return FUELS;
    if(path.includes("EquipmentType") && path.includes("/Boiler/")) return BOILER_TYPES;
    if(path.includes("EquipmentType")) return FURNACE_TYPES;
    if(path.endsWith("/CoolingSeason/Start")||path.endsWith("/CoolingSeason/End")||path.endsWith("/CoolingSeason/Design")) return HEATING_MONTHS;
    if(path.endsWith("/FansAndPump/Mode")||path.endsWith("/Mode")&&path.includes("/HeatingCooling/")) return HEATING_FAN_MODES;
    if(path.endsWith("/OutputCapacity")||path.endsWith("/RatedCapacity")) return HEATING_CAPACITY_MODES;
    if(path.endsWith("/CentralType")) return HEATING_AC_CENTRAL_TYPES;
    if(path.includes("/SupplementaryHeatingSystems/") && path.endsWith("/EnergySource")) return HEATING_SUPPLEMENTARY_FUELS;
    if(path.includes("/SupplementaryHeatingSystems/") && path.endsWith("/Type")) return HEATING_SUPP_EQUIP_TYPES;
    if(path.includes("/SupplementaryHeatingSystems/") && path.endsWith("/Usage")) return HEATING_SUPP_USAGE;
    if(path.includes("/SupplementaryHeatingSystems/") && path.endsWith("/LocationHeated")) return HEATING_SUPP_LOCATION;
    if(path.includes("/AdditionalOpenings/Opening") && !path.includes("/@")) return HEATING_ADDITIONAL_OPENING_TYPES;
    if(path.endsWith("/Function")) return HEATING_HP_FUNCTIONS;
    if(path.endsWith("/CutoffType")) return HEATING_HP_CUTOFF_TYPES;
    if(path.endsWith("/RatingType")) return HEATING_HP_RATING_TYPES;
    if(path.includes("/HeatPump/") && path.endsWith("/Type")) return HEATING_HP_EQUIP_TYPES;
    if(path.endsWith("/SourceTemperature/Use")) return HEATING_HP_SOURCE_TEMP_USE;
    if(path.includes("TankType")) return TANK_TYPES;
    if(path.includes("TankLocation")) return TANK_LOC;
    if(path.endsWith("/WeatherStation/Terrain")) return WEATHER_STATION_TERRAIN;
    if(path.includes("NaturalAirInfiltration/Specifications/BuildingSite/Terrain")) return BUILDING_SITE_TERRAIN;
    if(path.includes("NaturalAirInfiltration/Specifications/ExhaustDevicesTest/TestStatus")) return EXHAUST_DEPRESSURIZATION_STATUS;
    if(path.includes("NaturalAirInfiltration/Specifications/LocalShielding")&&(path.endsWith("/Walls")||path.endsWith("/Flue"))) return LOCAL_SHIELDING;
    if(path.includes("Terrain")) return TERRAIN;
    if(path.endsWith("/Walls")||path.endsWith("/Flue")) return SHIELDING;
    if(path.includes("InteriorLighting")) return LIGHTING;
    if(path.endsWith("/BathroomFaucets")) return BATHROOM_FAUCET_FLOW;
    if(path.endsWith("/Shower/Temperature")) return SHOWER_TEMPERATURE;
    if(path.endsWith("/Shower/FlowRate")) return SHOWER_FLOW_RATE;
    if(path.endsWith("/ClothesWasher/RatedValues")) return WASHER_RATED_VALUES;
    if(path.endsWith("/ClothesWasher/Temperature")) return WASHER_TEMPERATURE;
    if(path.endsWith("/DishWasher/RatedValues")) return WASHER_RATED_VALUES;
    if(path.endsWith("/ClothesDryer/RatedValue")) return DRYER_RATED_VALUES;
    if(path.endsWith("/Stove/RatedValue")) return STOVE_RATED_VALUES;
    if(path.endsWith("/Refrigerator")) return REFRIGERATOR_RATED;
    if(path.includes("ClothesDryer/Location")) return Object.fromEntries(internalDryerLocationOptions().map(i=>[i.id,i.label]));
    if(path.endsWith("/EnergySource") && (path.includes("/Stove/")||path.includes("/ClothesDryer/"))) return APPLIANCE_FUELS;
    if(path.endsWith("/AllowableRise")) return ALLOWABLE_RISE;
    if(path.endsWith("/Vermiculite")) return PROGRAM_VERMICULITE;
    if(path.endsWith("/YearBuilt")) return YEAR_BUILT;
    if(path.endsWith("/HouseType")) return codedDict(HOUSE_TYPES);
    if(path.endsWith("/PlanShape")) return PLAN_SHAPES;
    if(path.endsWith("/Storeys")) return STOREYS;
    if(path.endsWith("/FacingDirection")) return DIRS;
    if(path.endsWith("/ThermalMass")) return THERMAL_MASS;
    if(path.endsWith("/SoilCondition")) return SOIL;
    if(path.endsWith("/WaterLevel")) return WATER_LEVEL;
    if(path.endsWith("/WallColour")||path.endsWith("/RoofColour")) return COLOURS;
    if(path.endsWith("/Ownership")) return OWNERSHIP;
    if(path.endsWith("/OwnerOccupied")) return OWNER_OCCUPIED;
    if(path.endsWith("/Region")) return WEATHER_REGIONS;
    if(path.endsWith("/Location")) return weatherLocationDict();
    if(path.endsWith("/WindowTightness")) return windowTightnessDict();
    if(path.endsWith("/Array/Orientation")) return PV_ARRAY_ORIENTATION;
    if(path.endsWith("/Module/Type")) return PV_MODULE_TYPES;
    if(path.endsWith("/Declination/Direction")) return PV_DECLINATION_DIRECTION;
    return null;
  });
  root.querySelectorAll("[data-xml-path]").forEach(el=>el.addEventListener("change", renderSystemChips));
}

let responsiveSpecGroupMedia=null;
function bindResponsiveSpecGroups(root){
  if(!root) return;
  const nodes=root.querySelectorAll(".spec-group-collapsible");
  if(!nodes.length) return;
  const apply=()=>{
    const wide=window.matchMedia("(min-width:640px)").matches;
    nodes.forEach(d=>{
      if(wide) d.setAttribute("open","");
      else d.removeAttribute("open");
    });
  };
  apply();
  if(!responsiveSpecGroupMedia){
    responsiveSpecGroupMedia=window.matchMedia("(min-width:640px)");
    responsiveSpecGroupMedia.addEventListener("change",()=>{
      document.querySelectorAll(".spec-group-collapsible").forEach(d=>{
        if(responsiveSpecGroupMedia.matches) d.setAttribute("open","");
        else d.removeAttribute("open");
      });
    });
  }
}

