function syncHeatingFanPowerFields(root, path){
  const isCalculated=String(getPath(`${path}/@isCalculated`)||"true").toLowerCase()==="true";
  const isHeating=path.includes("/Type1/");
  const low=root.querySelector(`[data-xml-path="${path}/@low"]`);
  const high=root.querySelector(`[data-xml-path="${path}/@high"]`);
  const value=root.querySelector(`[data-xml-path="${path}/@value"]`);
  const lowWrap=low?.closest(".field");
  const highWrap=high?.closest(".field");
  if(isHeating){
    const lowLabel=lowWrap?.querySelector("span");
    if(lowLabel) lowLabel.textContent=isCalculated?"Calculated power low (W)":"User specified power (W)";
    if(highWrap) highWrap.hidden=!isCalculated;
    if(high) high.disabled=!isCalculated;
  }else{
    if(lowWrap) lowWrap.hidden=true;
    if(highWrap) highWrap.hidden=true;
    const valueWrap=value?.closest(".field");
    if(valueWrap) valueWrap.hidden=isCalculated;
    if(value) value.disabled=isCalculated;
  }
}
function bindHeatingScreen(root){
  const tabBtns=[...root.querySelectorAll("[data-heating-tab]")];
  const tabPanels=[...root.querySelectorAll("[data-heating-panel]")];
  const activateTab=(id)=>{
    heatingActiveTab=id;
    tabBtns.forEach(btn=>{
      const active=btn.dataset.heatingTab===id;
      btn.classList.toggle("is-active", active);
      btn.setAttribute("aria-selected", active?"true":"false");
    });
    tabPanels.forEach(panel=>{
      const active=panel.dataset.heatingPanel===id;
      panel.classList.toggle("is-active", active);
      panel.hidden=!active;
    });
  };
  tabBtns.forEach(btn=>btn.addEventListener("click",()=>activateTab(btn.dataset.heatingTab)));
  root.querySelectorAll("[data-heating-radio]").forEach(radio=>{
    radio.addEventListener("change",(e)=>{
      if(!e.target.checked) return;
      if(e.target.dataset.heatingRadio==="heating-type1"){
        setHeatingType1System(e.target.value);
        renderHeatingScreen();
      }else if(e.target.dataset.heatingRadio==="heating-type2"){
        setHeatingType2System(e.target.value);
        renderHeatingScreen();
      }
      saveSession();
    });
  });
  root.querySelector("[data-heating-shading-f280]")?.addEventListener("change",(e)=>{
    e.target.checked=true;
    setPath(`${HEATING_TYPE2}/@shadingInF280Cooling`, "AccountedFor");
    saveSession();
  });
  root.querySelector("[data-heating-radiant]")?.addEventListener("change",(e)=>{
    if(e.target.checked){
      ensureHeatingRadiantDefaults();
    }else{
      xp(HEATING_RADIANT)?.remove();
    }
    saveSession();
    renderHeatingScreen();
  });
  root.querySelector("[data-heating-additional-openings]")?.addEventListener("change",(e)=>{
    if(e.target.checked){
      ensureHeatingAdditionalOpeningsDefaults();
    }else{
      xp(HEATING_ADDITIONAL_OPENINGS)?.remove();
    }
    saveSession();
    renderHeatingScreen();
  });
  const suppInput=root.querySelector("[data-heating-supp-count]");
  const syncSuppStepper=(value)=>{
    const n=Math.max(0, Math.min(HEATING_SUPPLEMENTARY_MAX, Math.round(Number(value)||0)));
    if(suppInput) suppInput.value=String(n);
    const dec=root.querySelector('[data-heating-supp-step="decrease"]');
    const inc=root.querySelector('[data-heating-supp-step="increase"]');
    if(dec) dec.disabled=n<=0;
    if(inc) inc.disabled=n>=HEATING_SUPPLEMENTARY_MAX;
    return n;
  };
  const applySuppCount=(raw)=>{
    const prevActive=heatingActiveTab;
    const n=syncSuppStepper(raw);
    syncHeatingSupplementarySystems(n);
    const tabs=heatingTabDefinitions();
    heatingActiveTab=resolveHeatingActiveTab(tabs);
    if(prevActive.startsWith("suppl-") && tabs.some(t=>t.id===prevActive)) heatingActiveTab=prevActive;
    renderHeatingScreen();
    saveSession();
  };
  suppInput?.addEventListener("change",()=>applySuppCount(suppInput.value));
  suppInput?.addEventListener("input",()=>{
    const cleaned=String(suppInput.value).replace(/[^\d]/g,"");
    if(suppInput.value!==cleaned) suppInput.value=cleaned;
  });
  root.querySelector('[data-heating-supp-step="decrease"]')?.addEventListener("click",()=>{
    applySuppCount(syncSuppStepper(suppInput?.value)-1);
  });
  root.querySelector('[data-heating-supp-step="increase"]')?.addEventListener("click",()=>{
    applySuppCount(syncSuppStepper(suppInput?.value)+1);
  });
  syncSuppStepper(suppInput?.value||heatingSupplementaryCount());
  root.querySelectorAll("[data-heating-fan-power]").forEach(sel=>{
    const path=sel.dataset.heatingFanPower;
    const apply=()=>{
      const calculated=sel.value==="calculated";
      setPath(`${path}/@isCalculated`, calculated?"true":"false");
      syncHeatingFanPowerFields(root, path);
      saveSession();
    };
    sel.addEventListener("change", apply);
    syncHeatingFanPowerFields(root, path);
  });
}
function renderHeatingScreen(){
  ensureHeatingDefaults();
  const type1=heatingType1ActiveId();
  const type2=heatingType2ActiveId();
  if(type1==="baseboards") ensureHeatingBaseboardDefaults();
  else if(type1==="furnace") ensureHeatingFurnaceDefaults();
  else if(type1==="boiler") ensureHeatingBoilerDefaults();
  else if(type1==="combo") ensureHeatingComboDefaults();
  else if(type1==="p9") ensureHeatingP9Defaults();
  if(type2==="ac") ensureHeatingAcDefaults();
  else if(type2!=="none") ensureHeatingHeatPumpDefaults(type2);
  if(xp(HEATING_RADIANT)) ensureHeatingRadiantDefaults();
  if(xp(HEATING_ADDITIONAL_OPENINGS)) ensureHeatingAdditionalOpeningsDefaults();
  heatingSupplementarySystems().forEach((sys,i)=>ensureHeatingSupplementaryDefaults(i+1));
  const tabs=heatingTabDefinitions();
  heatingActiveTab=resolveHeatingActiveTab(tabs);
  const active=heatingActiveTab;
  const t=$("#screen-systems-heating-cooling"); if(!t) return;
  const meta=findScreen(buildSystemNav(),"heating-cooling");
  const panels=tabs.map(tab=>heatingTabPanelHTML(tab, active)).join("");
  t.innerHTML=wrapScreen(meta.title, meta.lead, `
    <div class="heating-editor spec-layout">
      ${heatingTabNavHTML(tabs, active)}
      <div class="basement-tab-panels heating-panels">
        ${panels}
      </div>
    </div>`);
  afterSystemBind(t);
  bindHeatingScreen(t);
}
