function generationPvSystems(){
  const container=xp(GENERATION_PV_PATH);
  if(!container) return [];
  return [...container.children].filter(n=>n.tagName==="System").sort((a,b)=>Number(a.getAttribute("rank")||0)-Number(b.getAttribute("rank")||0));
}
function generationPvPrototype(){
  const p=templateDoc?.evaluate(`${GENERATION_PV_PATH}/System[1]`, templateDoc, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
  if(p) return p.cloneNode(true);
  const sys=xmlDoc.createElement("System");
  sys.setAttribute("capacity", "0");
  const ei=xmlDoc.createElement("EquipmentInformation");
  sys.appendChild(ei);
  const array=xmlDoc.createElement("Array");
  array.setAttribute("area", "0");
  array.setAttribute("slope", "0");
  array.setAttribute("azimuth", "0");
  array.setAttribute("solarPanelOrientation", "0");
  const orientation=xmlDoc.createElement("Orientation");
  orientation.setAttribute("code", "1");
  const orientEn=xmlDoc.createElement("English");
  orientEn.textContent="Magnetic";
  const orientFr=xmlDoc.createElement("French");
  orientFr.textContent="Magnétique";
  orientation.appendChild(orientEn);
  orientation.appendChild(orientFr);
  array.appendChild(orientation);
  const declination=xmlDoc.createElement("Declination");
  declination.setAttribute("degrees", "0");
  declination.setAttribute("minutes", "0");
  const direction=xmlDoc.createElement("Direction");
  direction.setAttribute("code", "1");
  const dirEn=xmlDoc.createElement("English");
  dirEn.textContent="Westerly";
  const dirFr=xmlDoc.createElement("French");
  dirFr.textContent="Ouest";
  direction.appendChild(dirEn);
  direction.appendChild(dirFr);
  declination.appendChild(direction);
  array.appendChild(declination);
  sys.appendChild(array);
  const eff=xmlDoc.createElement("Efficiency");
  eff.setAttribute("miscellaneousLosses", "5");
  eff.setAttribute("otherPowerLosses", "0");
  eff.setAttribute("inverterEfficiency", "95");
  eff.setAttribute("gridAbsorptionRate", "100");
  sys.appendChild(eff);
  const module=xmlDoc.createElement("Module");
  module.setAttribute("efficiency", "13");
  module.setAttribute("cellTemperature", "45");
  module.setAttribute("coefficientOfEfficiency", "0.4");
  const type=xmlDoc.createElement("Type");
  type.setAttribute("code", "1");
  const en=xmlDoc.createElement("English");
  en.textContent="Mono-Si";
  const fr=xmlDoc.createElement("French");
  fr.textContent="Mono-Si";
  type.appendChild(en);
  type.appendChild(fr);
  module.appendChild(type);
  sys.appendChild(module);
  return sys;
}
function generationPvCount(){
  return generationPvSystems().length;
}
function generationPvSystemPath(rank){
  return `${GENERATION_PV_PATH}/System[${rank}]`;
}
function syncGenerationPhotovoltaicCapacity(){
  const total=generationPvSystems().reduce((sum,n)=>{
    const cap=Number(n.getAttribute("capacity")||0);
    return sum+(Number.isFinite(cap)?cap:0);
  }, 0);
  setPath(`${GENERATION_PATH}/@PhotovoltaicCapacity`, Number(total).toFixed(3));
}
function syncGenerationPvSystems(count){
  const target=Math.max(0, Math.min(GENERATION_PV_MAX, Number(count)||0));
  const gen=ensureEl(GENERATION_PATH);
  let container=xp(GENERATION_PV_PATH);
  if(!container && gen){
    container=xmlDoc.createElement("PhotovoltaicSystems");
    gen.appendChild(container);
  }
  if(!container) return target;
  const systems=generationPvSystems();
  while(systems.length<target){
    const rank=systems.length+1;
    const sys=generationPvPrototype().cloneNode(true);
    sys.setAttribute("rank", String(rank));
    if(!sys.getAttribute("capacity")) sys.setAttribute("capacity", "0");
    container.appendChild(sys);
    systems.push(sys);
    ensurePvSystemDefaults(`${GENERATION_PV_PATH}/System[${rank}]`);
  }
  while(systems.length>target){
    const last=systems.pop();
    if(last?.parentNode) last.parentNode.removeChild(last);
  }
  generationPvSystems().forEach((sys,i)=>sys.setAttribute("rank", String(i+1)));
  syncGenerationPhotovoltaicCapacity();
  return target;
}
function ensureGenerationDefaults(){
  const gen=ensureEl(GENERATION_PATH);
  if(!gen) return;
  if(!gen.hasAttribute("solarReady")) gen.setAttribute("solarReady", "false");
  if(!gen.hasAttribute("batteryStorage")) gen.setAttribute("batteryStorage", "false");
  if(!gen.hasAttribute("windEnergy")) gen.setAttribute("windEnergy", "false");
  if(!gen.hasAttribute("windEnergyContribution")) gen.setAttribute("windEnergyContribution", "0");
  if(!gen.hasAttribute("PhotovoltaicCapacity")) gen.setAttribute("PhotovoltaicCapacity", "0");
  let container=xp(GENERATION_PV_PATH);
  if(!container){
    container=xmlDoc.createElement("PhotovoltaicSystems");
    gen.appendChild(container);
  }
  const systems=generationPvSystems();
  systems.forEach(sys=>{
    const rank=sys.getAttribute("rank");
    if(rank) ensurePvSystemDefaults(`${GENERATION_PV_PATH}/System[${rank}]`);
  });
  const legacyCap=Number(getPath(`${GENERATION_PATH}/@PhotovoltaicCapacity`)||0);
  if(!systems.length && legacyCap>0){
    syncGenerationPvSystems(1);
    const first=generationPvSystems()[0];
    if(first) first.setAttribute("capacity", Number(legacyCap).toFixed(3));
    syncGenerationPhotovoltaicCapacity();
  }
}
function generationPvIsGeographic(path){
  return String(getPath(`${path}/Array/Orientation/@code`)||"1")==="2";
}
function ensurePvSystemDefaults(path){
  ensureEl(`${path}/EquipmentInformation`);
  const array=ensureEl(`${path}/Array`);
  if(array && !array.hasAttribute("solarPanelOrientation")) array.setAttribute("solarPanelOrientation", "0");
  if(array){
    const orient=array.getAttribute("solarPanelOrientation")||"0";
    array.setAttribute("azimuth", pvAzimuthFromSolarPanelOrientation(orient));
  }
  if(!xp(`${path}/Array/Orientation`)) applyCodedDefault(`${path}/Array/Orientation`, "1", PV_ARRAY_ORIENTATION);
  const decl=ensureEl(`${path}/Array/Declination`);
  if(decl){
    if(!decl.hasAttribute("degrees")) decl.setAttribute("degrees", "0");
    if(!decl.hasAttribute("minutes")) decl.setAttribute("minutes", "0");
  }
  if(!xp(`${path}/Array/Declination/Direction`)) applyCodedDefault(`${path}/Array/Declination/Direction`, "1", PV_DECLINATION_DIRECTION);
  const module=ensureEl(`${path}/Module`);
  if(module){
    if(!module.hasAttribute("efficiency")) module.setAttribute("efficiency", PV_MODULE_PRESETS["1"].efficiency);
    if(!module.hasAttribute("cellTemperature")) module.setAttribute("cellTemperature", PV_MODULE_PRESETS["1"].cellTemperature);
    if(!module.hasAttribute("coefficientOfEfficiency")) module.setAttribute("coefficientOfEfficiency", PV_MODULE_PRESETS["1"].coefficientOfEfficiency);
  }
  if(!xp(`${path}/Module/Type`)) applyCodedDefault(`${path}/Module/Type`, "1", PV_MODULE_TYPES);
  const eff=ensureEl(`${path}/Efficiency`);
  if(eff){
    Object.entries(PV_EFFICIENCY_DEFAULTS).forEach(([attr, val])=>{
      if(!eff.hasAttribute(attr)) eff.setAttribute(attr, val);
    });
  }
}
