function validation(){
  const errors=[],warnings=[]; const ids=xpa("/HouseFile/House/Components//*[@id]").map(n=>n.getAttribute("id")); const dup=ids.filter((id,i)=>ids.indexOf(id)!==i); if(dup.length)errors.push("Duplicate component IDs: "+[...new Set(dup)].join(", "));
  xpa("//*[@idref]").forEach(n=>{const ref=n.getAttribute("idref");if(!xp(`//*[@id='${ref}']`))errors.push(`Missing idref ${ref} used by <${n.tagName}>`);});
  if(!xp("/HouseFile/Version"))errors.push("Missing HouseFile/Version"); if(!xp("/HouseFile/House/Components"))errors.push("Missing House/Components");
  const postal=String(getPath(`${CLIENT_STREET}/PostalCode`)||"").trim();
  if(postal){
    const formatted=formatOntarioPostal(postal);
    if(formatted!==postal){
      setPath(`${CLIENT_STREET}/PostalCode`, formatted);
      setPath(`${CLIENT_MAIL}/PostalCode`, formatted);
    }
    if(!isOntarioPostal(formatted)){
      errors.push("Postal code must be Ontario format only (starts with K, L, M, N, or P), e.g. M5V 3L9.");
    }
  }
  if(xpa("/HouseFile/House/Components/Wall").length===0)warnings.push("No above-grade walls."); if(xpa("/HouseFile/House/Components/Ceiling").length===0)warnings.push("No ceilings.");
  if(!xp("/HouseFile/AllResults/Results[@houseCode='SOC']")){
    if(xp("/HouseFile/AllResults")){
      warnings.push("AllResults exist but House with standard operating conditions (SOC) was not found.");
    }else{
      warnings.push("No AllResults in this file yet. Import a calculated .h2k or run HOT2000 Desktop once to create Net GJ/a.");
    }
  }
  return {errors,warnings};
}
let lastSocReport=null;
let reviewValidationPassed=false;
function isEnergyModelPath(path=""){
  return /\/House\/(Components|HeatingCooling|Ventilation|BaseLoads|Temperatures|NaturalAirInfiltration|Generation)\b/.test(String(path));
}
function invalidateReviewUnlock(message=""){
  reviewValidationPassed=false;
  lastSocReport=null;
  const v=runValidation();
  const el=$("#validationResult");
  if(el && !v.errors.length && message){
    el.className="validation neutral";
    el.innerHTML=message;
  }
  const panel=$("#socEnergyPanel");
  if(panel && panel.classList.contains("is-idle")){
    panel.innerHTML=`<p class="soc-energy-idle">Model changed. Click top-bar Validate again. Generate Net (GJ/a) stays off until validation passes${hasSocResults()?"":" and SOC is present"}.</p>`;
  }
  return v;
}
function numOrNull(v){
  if(v==null||v==="") return null;
  const n=Number(v);
  return Number.isFinite(n)?n:null;
}
function formatGJ(n, digits=2){
  if(n==null||!Number.isFinite(n)) return "—";
  return `${Number(n).toFixed(digits)} GJ/a`;
}
function formatNum(n, digits=1){
  if(n==null||!Number.isFinite(n)) return "—";
  return Number(n).toFixed(digits);
}
function formatNetGJa(n){
  // House with standard operating conditions Net GJ/a — always 2 decimals on all viewports.
  if(n==null||n==="") return "—";
  const x=Number(n);
  if(!Number.isFinite(x)) return "—";
  return x.toFixed(2);
}
function englishPath(path){
  return xp(path)?.querySelector(":scope > English")?.textContent?.trim() || xp(path)?.textContent?.trim() || "";
}
function tsvValue(name){
  return xp(`/HouseFile/Program/Results/Tsv/${name}`)?.getAttribute("value") ?? "";
}
function tsvNum(name){
  return numOrNull(tsvValue(name));
}
function attrNum(el, name){
  return numOrNull(el?.getAttribute?.(name));
}
function sumNums(...vals){
  let t=0, any=false;
  for(const v of vals){
    if(v==null||!Number.isFinite(v)) continue;
    t+=v; any=true;
  }
  return any?t:null;
}
function mjToKWh(mj){
  return mj==null?null:mj/3.6;
}
function gjToMJ(gj){
  return gj==null?null:gj*1000;
}
function formatMoney(n, digits=2){
  if(n==null||!Number.isFinite(n)) return "—";
  return `$${n.toFixed(digits)}`;
}
function formatUnit(n, unit, digits=1){
  if(n==null||!Number.isFinite(n)) return "—";
  return `${n.toFixed(digits)}${unit?` ${unit}`:""}`;
}
