  const label=node.querySelector(":scope > Labels > English")?.textContent?.trim() || "House with standard operating conditions";
  const cons=node.querySelector(":scope > Annual > Consumption");
  if(!cons) return null;
  const elec=cons.querySelector(":scope > Electrical");
  const gas=cons.querySelector(":scope > NaturalGas");
  const oil=cons.querySelector(":scope > Oil");
  const propane=cons.querySelector(":scope > Propane");
  const wood=cons.querySelector(":scope > Wood");
  const space=cons.querySelector(":scope > SpaceHeating");
  const dhw=cons.querySelector(":scope > HotWater");
