function buildSocPdfBlob(report){
  const blocks=buildEnerGuideHouseReportLines(report);
  const pageW=612, pageH=792, margin=40;
  const maxCharsFor=size=>Math.max(40, Math.floor((pageW-margin*2)/(size*0.52)));
  const pages=[];
  let y=pageH-margin;
  let cmds=[];
  const flush=()=>{ pages.push(cmds.join("\n")); cmds=[]; y=pageH-margin; };
  const ensure=(need)=>{ if(y-need<margin) flush(); };
  for(const b of blocks){
    if(b.kind==="sp"){ y-=b.gap||4; continue; }
    if(b.kind==="h"){
      ensure(b.size+10);
      cmds.push("BT");
      cmds.push(`/F1 ${b.size} Tf`);
      cmds.push(`${margin} ${y.toFixed(2)} Td`);
      cmds.push(`(${pdfSafeText(b.text)}) Tj`);
      cmds.push("ET");
      y-=b.size+2;
      // underline
      cmds.push(`${margin} ${y.toFixed(2)} m ${pageW-margin} ${y.toFixed(2)} l S`);
      y-=b.gap||5;
      continue;
    }
    const wrapped=pdfWrap(b.text, maxCharsFor(b.size));
    for(const line of wrapped){
      ensure(b.size+3);
      cmds.push("BT");
      cmds.push(`/F1 ${b.size} Tf`);
      cmds.push(`${margin} ${y.toFixed(2)} Td`);
      cmds.push(`(${pdfSafeText(line)}) Tj`);
      cmds.push("ET");
      y-=b.size+(b.gap||2);
    }
  }
  if(cmds.length) flush();
  if(!pages.length) pages.push("BT /F1 12 Tf 48 744 Td (House report) Tj ET");

  const objects=[];
  objects[1]="<< /Type /Catalog /Pages 2 0 R >>";
  const fontObjNum=3+pages.length*2;
  objects[fontObjNum]="<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>";
  const kids=[];
  let obj=3;
  for(let i=0;i<pages.length;i++){
    const contentNum=obj+1;
    const stream=pages[i];
    objects[obj]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageW} ${pageH}] /Contents ${contentNum} 0 R /Resources << /Font << /F1 ${fontObjNum} 0 R >> >> >>`;
    objects[contentNum]=`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`;
    kids.push(`${obj} 0 R`);
    obj+=2;
  }
  objects[2]=`<< /Type /Pages /Kids [${kids.join(" ")}] /Count ${pages.length} >>`;

  let pdf=`%PDF-1.4\n`;
  const offsets=[0];
  const maxObj=Math.max(...Object.keys(objects).map(Number));
  for(let n=1;n<=maxObj;n++){
    if(!objects[n]) continue;
    offsets[n]=pdf.length;
    pdf+=`${n} 0 obj\n${objects[n]}\nendobj\n`;
  }
  const xref=pdf.length;
  pdf+=`xref\n0 ${maxObj+1}\n`;
  pdf+="0000000000 65535 f \n";
  for(let n=1;n<=maxObj;n++){
    const off=offsets[n]||0;
    pdf+=`${String(off).padStart(10,"0")} 00000 n \n`;
  }
  pdf+=`trailer\n<< /Size ${maxObj+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  return new Blob([pdf], {type:"application/pdf"});
}
function reportPdfFilename(report){
  const base=(report?.identity?.client||"energuide-soc-house-report")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,"-")
    .replace(/^-+|-+$/g,"")
    .slice(0,48)||"energuide-soc-house-report";
  return `${base}-soc-house-report.pdf`;
}
function downloadSocPdfReport(){
  const v=runValidation();
  if(v.errors.length){ toast("Fix validation errors first"); return; }
  const report=lastSocReport || generateSocNetGJa();
  if(!report) return;
  try{
    const blob=buildSocPdfBlob(report);
    const name=reportPdfFilename(report);
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");
    a.href=url;
    a.download=name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(()=>URL.revokeObjectURL(url), 2000);
    toast(`Downloaded ${name}`);
  }catch(err){
    console.error(err);
    toast("Could not create PDF report");
  }
}
function buildXmlString({forHot2000=false}={}){
  syncProgramModeFromUI();
  syncMailingFromClient();
  syncWeatherRegionToClient();
  applyFuelRateBlocks(getFuelRatePeriod());
  const clone=xmlDoc.cloneNode(true);
  if(forHot2000){
    // HOT2000 Desktop does not recognize @ratePeriod. Leaving it on FuelCosts makes the
    // Fuel Cost screen fall back to Annual. Strip it so Desktop can match monthly library rates.
    const fc=clone.querySelector("FuelCosts");
    if(fc) fc.removeAttribute("ratePeriod");
    const bl=clone.querySelector("BaseLoads");
    if(bl) bl.removeAttribute("userSpecifiedUsage");
    clone.querySelectorAll("ClothesWasher, DishWasher, ClothesDryer").forEach(n=>n.removeAttribute("installed"));
  }
  return `<?xml version="1.0" encoding="UTF-8"?>\n`+new XMLSerializer().serializeToString(clone.documentElement);
}
function serializeForExport(){
  return buildXmlString({forHot2000:true});
}
function exportH2K(){const v=runValidation();if(v.errors.length){toast("Fix validation errors before exporting");return;}let name=$("#exportName").value.trim()||"web-model.h2k";if(!name.toLowerCase().endsWith(".h2k"))name+=".h2k";const blob=new Blob([serializeForExport()],{type:"application/xml;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("H2K file exported");}
function clearSession(){try{sessionStorage.removeItem(SESSION_KEY);}catch(e){}}
function saveSession(){
  if(!xmlDoc) return;
  try{
    sessionStorage.setItem(SESSION_KEY, JSON.stringify({
      version: APP_VERSION,
      xml: buildXmlString({forHot2000:false}),
      name: $("#exportName")?.value || "web-model.h2k"
    }));
  }catch(e){}
}
function restoreSession(){
  try{
    const raw=sessionStorage.getItem(SESSION_KEY);
    if(!raw) return false;
    const data=JSON.parse(raw);
    if(data.version!==APP_VERSION){clearSession();return false;}
    loadDoc(parseXML(data.xml), data.name||"web-model.h2k");
    return true;
  }catch(e){clearSession();return false;}
}
function normalizeFieldLimits(){
  const builder=getPath("/HouseFile/ProgramInformation/File/BuilderName");
  if(builder.length>32) setPath("/HouseFile/ProgramInformation/File/BuilderName", builder.slice(0,32));
  setPath("/HouseFile/House/Specifications/@effectiveMassFraction","1.00");
  applyCodedDefault("/HouseFile/ProgramInformation/File/Ownership","1",OWNERSHIP);
  ensureBuildingTypeDefaults();
  applyCodedDefault("/HouseFile/House/Specifications/YearBuilt","1",YEAR_BUILT);
  applyCodedDefault("/HouseFile/House/Specifications/ThermalMass","1",THERMAL_MASS);
  applyCodedDefault("/HouseFile/House/Specifications/SoilCondition","1",SOIL);
  applyCodedDefault("/HouseFile/House/Specifications/WaterLevel","2",WATER_LEVEL);
  applyCodedDefault("/HouseFile/House/Specifications/WallColour","10",COLOURS,{value:"0.4"});
  applyCodedDefault("/HouseFile/House/Specifications/RoofColour","10",COLOURS,{value:"0.4"});
  setPath("/HouseFile/House/Specifications/@defaultRoofCavity","true");
  if(!getPath("/HouseFile/House/Specifications/@eligibleForNBC")) setPath("/HouseFile/House/Specifications/@eligibleForNBC","false");
  setPath(`${CLIENT_STREET}/Province`, "ONTARIO");
  setPath(`${CLIENT_MAIL}/Province`, "ONTARIO");
  ensureWindowTightnessDefault();
  ensureFuelCostDefaults();
  ensureProgramModeDefault();
  syncWeatherRegionToClient();
}
function loadDoc(doc,name="web-model.h2k",{autoValidate=false}={}){
  xmlDoc=doc;
  infiltrationElaMode=false;
  lastSocReport=null;
  reviewValidationPassed=false;
  normalizeFieldLimits();
  const u=xmlDoc.documentElement.getAttribute("uiUnits");
  unitMode=u==="Metric"?"metric":"imperial";
  $("#unitMode").value=unitMode;
  syncProgramModeUI();
  renderAllForms();
  renderComponents();
  $("#exportName").value=name.replace(/\.(xml|h2k)$/i,"")+"-web.h2k";
  if(autoValidate){
    reviewValidationPassed=!validation().errors.length;
  }
  runValidation();
  saveSession();
  return {ok:!!reviewValidationPassed, soc:hasSocResults()};
}
